{"command":"cat << 'EOF' > main_script.py
import os, sys, json, argparse, fnmatch
import config

def get_lang(name):
    base = os.path.basename(name).lower()
    if base in config.ext_to_lang: return config.ext_to_lang[base]
    parts = base.split('.')
    if len(parts) > 1 and parts[-1] in config.ext_to_lang: return config.ext_to_lang[parts[-1]]
    return None

def parse_file(filepath, lang):
    syns = config.lang_syntaxes.get(lang, {"single": [], "multi": []})
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except Exception:
        return None

    code = 0; comm = 0; blank = 0
    in_multi = False; multi_end = None
    in_str = False; str_char = None

    single_markers = syns.get("single", [])
    multi_markers = syns.get("multi", [])
    single_markers.sort(key=len, reverse=True)
    multi_markers.sort(key=lambda x: len(x[0]), reverse=True)

    for line in lines:
        line_clean = line.strip()
        if not line_clean:
            if in_multi: comm += 1
            elif in_str: code += 1
            else: blank += 1
            continue
        i = 0; has_code = False; has_comm = False
        while i < len(line_clean):
            if in_str:
                if line_clean[i] == '\\' and i+1 < len(line_clean): i += 2; continue
                if line_clean[i] == str_char: in_str = False; i += 1
                else: i += 1
                has_code = True; continue
            if in_multi:
                if line_clean[i:i+len(multi_end)] == multi_end:
                    in_multi = False; i += len(multi_end)
                else: i += 1
                has_comm = True; continue
            if line_clean[i] in ['"', "'", '`']:
                in_str = True; str_char = line_clean[i]; i += 1
                has_code = True; continue
            matched_multi = False
            for s, e in multi_markers:
                if line_clean[i:i+len(s)] == s:
                    in_multi = True; multi_end = e; i += len(s)
                    has_comm = True; matched_multi = True; break
            if matched_multi: continue
            matched_single = False
            for s in single_markers:
                if line_clean[i:i+len(s)] == s:
                    has_comm = True; i = len(line_clean); matched_single = True; break
            if matched_single: continue
            if line_clean[i] not in ' \t\r\n': has_code = True
            i += 1
        if has_code: code += 1
        elif has_comm: comm += 1
        else: blank += 1
    return {"blanks": blank, "code": code, "comments": comm, "lines": len(lines)}

def print_table(stats, show_files=False, sort_by=None):
    print("━" * 81)
    print(" Language              Files        Lines         Code     Comments       Blanks")
    print("━" * 81)

    tot_files = tot_lines = tot_code = tot_comm = tot_blanks = 0

    # Sort
    items = list(stats.items())
    if sort_by:
        # files, lines, blanks, code, comments
        items.sort(key=lambda x: x[1][sort_by], reverse=True)
    else:
        items.sort(key=lambda x: x[0]) # alphabetical

    for lang, s in items:
        tot_files += len(s['reports'])
        tot_lines += s['lines']
        tot_code += s['code']
        tot_comm += s['comments']
        tot_blanks += s['blanks']

        name = lang
        if len(name) > 18: name = name[:17] + "|"
        print(f" {name:<21} {len(s['reports']):>5} {s['lines']:>12} {s['code']:>12} {s['comments']:>12} {s['blanks']:>12}")

        if show_files:
            print("─" * 81)
            reps = s['reports']
            if sort_by: reps.sort(key=lambda x: x['stats'][sort_by], reverse=True)
            for r in reps:
                fname = r['name']
                if len(fname) > 27: fname = "|" + fname[-26:]
                print(f" {fname:<27} {r['lines']:>12} {r['stats']['code']:>12} {r['stats']['comments']:>12} {r['stats']['blanks']:>12}")
            print("━" * 81)

    if not show_files:
        print("━" * 81)
    print(f" {'Total':<21} {tot_files:>5} {tot_lines:>12} {tot_code:>12} {tot_comm:>12} {tot_blanks:>12}")
    print("━" * 81)

def match_exclude(path, excludes):
    for exc in excludes:
        if fnmatch.fnmatch(path, exc) or fnmatch.fnmatch(os.path.basename(path), exc):
            return True
    return False

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('-l', '--languages', action='store_true')
    parser.add_argument('-t', '--type')
    parser.add_argument('-e', '--exclude', action='append', default=[])
    parser.add_argument('-f', '--files', action='store_true')
    parser.add_argument('-s', '--sort')
    parser.add_argument('-o', '--output')
    parser.add_argument('input', nargs='*', default=['.'])
    args = parser.parse_args()

    if args.languages:
        with open('full_langs.txt') as f: print(f.read(), end='')
        return

    stats = {}

    excludes = ['.git'] + args.exclude

    types = None
    if args.type:
        types = [t.strip().lower() for t in args.type.split(',')]

    for inp in args.input:
        if os.path.isfile(inp):
            files = [inp]
        else:
            files = []
            for root, dirs, fnames in os.walk(inp):
                # read .gitignore if present (simplified)
                gi = os.path.join(root, '.gitignore')
                if os.path.isfile(gi):
                    with open(gi) as f:
                        for line in f:
                            if line.strip() and not line.startswith('#'):
                                excludes.append(line.strip())

                # filter dirs
                dirs[:] = [d for d in dirs if not match_exclude(os.path.join(root, d), excludes)]
                for f in fnames:
                    path = os.path.join(root, f)
                    if not match_exclude(path, excludes):
                        files.append(path)

        for f in files:
            lang = get_lang(f)
            if not lang: continue
            if types and lang.lower() not in types: continue

            res = parse_file(f, lang)
            if not res: continue

            if lang not in stats:
                stats[lang] = {'blanks':0, 'code':0, 'comments':0, 'lines':0, 'reports':[]}
            stats[lang]['blanks'] += res['blanks']
            stats[lang]['code'] += res['code']
            stats[lang]['comments'] += res['comments']
            stats[lang]['lines'] += res['lines']
            stats[lang]['reports'].append({
                'name': f if f.startswith('./') else ('./'+f if not os.path.isabs(f) else f),
                'stats': res,
                'lines': res['lines']
            })

    if args.output == 'json':
        out = {}
        for l, s in stats.items():
            reps = []
            for r in s['reports']:
                reps.append({
                    "stats": {"blanks": r['stats']['blanks'], "code": r['stats']['code'], "comments": r['stats']['comments'], "blobs": {}},
                    "name": r['name']
                })
            out[l] = {
                "blanks": s['blanks'], "code": s['code'], "comments": s['comments'],
                "reports": reps, "children": {}, "inaccurate": False
            }
        # Total
        tot = {"blanks":0, "code":0, "comments":0, "reports":[], "children": {}, "inaccurate": False}
        for l, s in out.items():
            if l == 'Total': continue
            tot['blanks'] += s['blanks']
            tot['code'] += s['code']
            tot['comments'] += s['comments']
            tot['children'][l] = s['reports']
        out['Total'] = tot
        print(json.dumps(out, separators=(',', ':')))
    else:
        print_table(stats, args.files, args.sort)

if __name__ == '__main__':
    main()
